    /// <summary>
    /// The find method of the METVendSiteSettingsSetup table.
    /// </summary>
    /// <param name = "_recId">The record id to find.</param>
    /// <param name = "_forUpdate">To update the record or not.</param>
    /// <param name = "_concurrencyModel">The concurrency model.</param>
    /// <returns>Returns the buffer of the METVendSiteSettingsSetup table record.</returns>
    public static METVendSiteSettingsSetup find(
        RecId _recId,
        boolean _forUpdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METVendSiteSettingsSetup metVendSiteSettingsSetup;
        
        metVendSiteSettingsSetup.selectForUpdate(_forUpdate);
        if (_forUpdate  && _concurrencyModel != ConcurrencyModel::Auto)
        {
            metVendSiteSettingsSetup.concurrencyModel(_concurrencyModel);
        }

        select firstonly metVendSiteSettingsSetup
            where metVendSiteSettingsSetup.RecId == _recId;

        return metVendSiteSettingsSetup;
    }

/// <summary>
/// The insert method of the table.
/// </summary>
public void insert()
{
    this.updateLevel();
    super();
}

/// <summary>
/// The update method of the table.
/// </summary>
public void update()
{
    this.updateLevel();
    super();
}

/// <summary>
/// Updated the level of the record.
/// </summary>
private void updateLevel()
{
    if (this.AssignedVendorAccount && this.AssignedSite == '' && this.AssignedWH == '')
    {
        this.Level = 0;
    }
    else if (this.AssignedVendorAccount && this.AssignedSite && this.AssignedWH == '')
    {
        this.Level = 1;
    }
    else if (this.AssignedVendorAccount && this.AssignedSite && this.AssignedWH)
    {
        this.Level = 2;
    }
}

    /// <summary>
    /// find Email address based on Vendor Site Settings of a Purchase Order
    /// </summary>
    /// <param name = "_purchId">Purchase Id of the purchase order</param>
    /// <returns>Email Address string</returns>
    public static METVendSiteSetupPOEmailAddresses getPurchOrderEmailAddress(PurchId _purchId)
    {
        PurchTable purchTable;

        select firstonly OrderAccount,InventSiteId,InventLocationId from purchTable
            where purchTable.PurchId == _purchId;

        METVendSiteSettingsSetup METVendSiteSettingsSetup;

        //first find based on vendor Account, Site and WH combination
        select firstonly POEmailAddresses from METVendSiteSettingsSetup
            where   METVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount &&
                    METVendSiteSettingsSetup.AssignedSite          == purchTable.InventSiteId &&
                    METVendSiteSettingsSetup.AssignedWH            == purchTable.InventLocationId;

        if(METVendSiteSettingsSetup.POEmailAddresses)
        {
            return METVendSiteSettingsSetup.POEmailAddresses;
        }

        //if not first, find based on vendor Account, Site combination
        select firstonly POEmailAddresses from METVendSiteSettingsSetup
            where   METVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount &&
                    METVendSiteSettingsSetup.AssignedSite          == purchTable.InventSiteId &&
                    METVendSiteSettingsSetup.Level                 == 1;
        if(METVendSiteSettingsSetup.POEmailAddresses)
        {
            return METVendSiteSettingsSetup.POEmailAddresses;
        }

        //if not second as well, find based on vendor Account, if not found, this will return blank
        select firstonly POEmailAddresses from METVendSiteSettingsSetup
            where   METVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount &&
                    METVendSiteSettingsSetup.Level                 == 0;
        return METVendSiteSettingsSetup.POEmailAddresses;
    }

    /// <summary>
    /// Check weather the record exists or not 
    /// </summary>
    /// <param name = "_purchId">PurchId</param>
    /// <returns>Boolean value</returns>
    public static boolean existsPOVendSiteRecord(PurchId _purchId)
    {
        PurchTable purchTable;
        METVendSiteSettingsSetup METVendSiteSettingsSetup;

        select firstonly OrderAccount from purchTable
                where purchTable.PurchId == _purchId
            join firstonly RecId from METVendSiteSettingsSetup
                where METVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount;

        if(METVendSiteSettingsSetup)
        {
            return true;
        }
        return false;
    }

    /// <summary>
    /// The validateWrite method of the table
    /// </summary>
    /// <returns>True or false</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (ret)
        {
            if (this.AssignedWH && !this.AssignedSite)
            {
                throw Error("@MET:METSiteWarehouseError");
            }

            if (this.POEmailAddresses == '' && (this.POSubMode != METConstants::EDI && this.POSubMode != ''))                
            {
                throw error("@MET:METPOEmailAddressError");
            }

            if (!this.DefaultItemCoverWH
                    && this.DefaultPlannedOrderType == METVendSiteSetupDefaultPlannedOrderType::Transfer)
            {
                throw error("@MET:METDefaulMainWHError");
            }

            if (this.POSubMode == METConstants::Email || this.POSubMode == '')
            {
                this.FASetting = NoYes::No;
            }

            if (this.ETradeSetting == NoYes::No)
            {
                this.ASNSetting = NoYes::No;
                this.EInvoiceSetting = NoYes::No;
            }

            if (this.ASNSetting == NoYes::No)
            {
                this.ExpressReceiptSetting = NoYes::No;
            }

            if (this.ETradeSetting == NoYes::No)
            {
                this.POASetting = NoYes::No;
            }

            if( this.AssignedWH )
            {
                InventLocation		InventLocation;
                METInventLocation METInventLocation;
                
                select firstonly METinventLocation
                    exists join inventLocation
                    where inventLocation.InventLocationId == this.AssignedWH
                    && METinventLocation.inventLocation == inventLocation.recId;

                this.VendorPromoDaysAfter = this.VendorPromoDaysAfter? this.VendorPromoDaysAfter: METInventLocation.VendorPromoDaysAfter;
                this.VendorPromoDaysBefore = this.VendorPromoDaysBefore? this.VendorPromoDaysBefore: METInventLocation.VendorPromoDaysBefore;
            }

        }
    
        return ret;
    }

    /// <summary>
    /// Runs the batch job in the background
    /// </summary>
    private void runLeadTimeUpdateBatch()
    {
        boolean run = false;
        METVendSiteSettingsSetup metVendSiteSettingsSetupLocal;
        METVendParameters metVendParameters = METVendParameters::find();
        BatchHeader batchHeader;
        METVendSiteLeadTimeUpdController metVendSiteLeadTimeUpdController = new METVendSiteLeadTimeUpdController();  
        METVendSiteLeadTimeUpdContract metVendSiteLeadTimeUpdContract = metVendSiteLeadTimeUpdController.getDataContractObject();
        metVendSiteLeadTimeUpdContract.parmRecId(this.RecId);
        metVendSiteLeadTimeUpdContract.parmIsLevelZero(NoYes::No);
        
        if (metVendParameters.EnableLeadTimeUpdateVendSite && this.RecId)
        {
            run = true;            
        }

        // If it is a level 0 record
        if (this.AssignedVendorAccount && this.AssignedSite == '' && this.AssignedWH == '')
        {
            // Look for record other than this record where level > 0
            select firstonly RecId from metVendSiteSettingsSetupLocal
                where metVendSiteSettingsSetupLocal.AssignedVendorAccount == this.AssignedVendorAccount
                && metVendSiteSettingsSetupLocal.Level > 0
                && metVendSiteSettingsSetupLocal.RecId != this.RecId;

            if (metVendSiteSettingsSetupLocal.RecId)
            {
                run = false;
            }

            metVendSiteLeadTimeUpdContract.parmIsLevelZero(NoYes::Yes);
        }

        if (run)
        {
            batchHeader = batchHeader::construct();
            batchHeader.addTask(metVendSiteLeadTimeUpdController);
            batchHeader.save();
        }
    }

    /// <summary>
    /// The modifiedField method of the table
    /// </summary>
    /// <param name = "_fieldId">FieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METVendSiteSettingsSetup, DefaultItemCovLeadTime):
                this.write();
                this.runLeadTimeUpdateBatch();
                break; 
            
            case fieldNum(METVendSiteSettingsSetup, AssignedWH):
                this.initFromInventLocation();
                break;
                
        }
    }

    /// <summary>
    /// Initiate from invent warehouse
    /// </summary>
    public void initFromInventLocation()
    {
        InventLocation InventLocation;
        METInventLocation METInventLocation;
        select firstonly METinventLocation
            exists join inventLocation
            where inventLocation.InventLocationId == this.AssignedWH
            && METinventLocation.inventLocation == inventLocation.recId;

        this.VendorPromoDaysAfter = METInventLocation.VendorPromoDaysAfter;
        this.VendorPromoDaysBefore = METInventLocation.VendorPromoDaysBefore;

    }
